30: // ---------------------------------------------------------------------------
31: // New Orchestrator API Tests
32: // ---------------------------------------------------------------------------
33: 
34: /// Verify the initial state is Idle.
35: TEST_F(OtaUpdateManagerTest, DefaultState_IsIdle) {
36:     EXPECT_EQ(OTAState::Idle, manager.getState());
37: }
38: 
39: /// checkForUpdate() must return false if begin() was never called.
40: TEST_F(OtaUpdateManagerTest, CheckForUpdate_WithoutBegin_ReturnsFalse) {
41:     EXPECT_FALSE(manager.checkForUpdate());
42: }
43: 
44: /// performUpdate() without begin() should set state to Error on native.
45: TEST_F(OtaUpdateManagerTest, PerformUpdate_WithoutBegin_SetsError) {
46:     manager.performUpdate();
47:     EXPECT_EQ(OTAState::Error, manager.getState());
48: }
49: 
50: /// getLastOtaError() should return nullptr initially.
51: TEST_F(OtaUpdateManagerTest, GetLastOtaError_Default_ReturnsNull) {
52:     EXPECT_EQ(nullptr, manager.getLastOtaError());
53: }
54: 
55: /// performUpdate() after begin() transitions state to Checking and notifies
56: /// the persistent worker task. On native the worker runs synchronously via the
57: /// xTaskCreateWithCaps stub but exits at ulTaskNotifyTake before running the
58: /// pipeline — so state stays at Checking (not Error) after performUpdate().
59: TEST_F(OtaUpdateManagerTest, PerformUpdate_AfterBegin_TransitionsToChecking) {
60:     Application app;
61:     manager.begin(app);
62:     manager.performUpdate();
63:     EXPECT_EQ(OTAState::Checking, manager.getState());
64:     EXPECT_EQ(nullptr, manager.getLastOtaError());
65: }
66: 
67: /// checkForUpdate() after begin() with no repo should return false.
68: TEST_F(OtaUpdateManagerTest, CheckForUpdate_NoRepo_ReturnsFalse) {
69:     Application app;
70:     manager.begin(app);
71:     EXPECT_FALSE(manager.checkForUpdate());
72:     // State should return to Idle (not stuck in Checking)
73:     EXPECT_EQ(OTAState::Idle, manager.getState());
74: }
