130:     manager.resetConfig();
131:     JsonDocument doc;
132:     JsonObject section = doc.to<JsonObject>();
133:     manager.serializeConfig(section);
134:     ASSERT_TRUE(section["updatesEnabled"].is<bool>());
135:     EXPECT_TRUE(section["updatesEnabled"].as<bool>());
136: }
137: 
138: /// applyConfig()/serializeConfig() must round-trip updatesEnabled in both states.
139: TEST_F(OtaUpdateManagerTest, Config_UpdatesEnabled_RoundTrips) {
140:     // false → persisted as false
141:     JsonDocument inDoc;
142:     inDoc["updatesEnabled"] = false;
143:     manager.applyConfig(inDoc.as<JsonObject>());
144: 
